def variance(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the variance of the
    numbers in this dataset.
    Variance is the average of the squared differences from the mean:
    var(x) = average[ (x_i - average(x))^2 ]
    """
    if len(numbers) == 0:
        return float('nan')
    else:
        mean_num = mean(numbers)
