def parse_paren_group(paren_group: str) -> int:
    """ Given a group of parenthesis, returns the deepest level of nesting"""
    if paren_group == '':
        return 0

    stack_level = 0
    max_level = 0
    for p in paren_group:
        if p == '(':
            stack_level += 1
            if stack_level > max_level:
                max_level = stack_level
        else:
            stack_level -= 1

    return max_level


